```cpp
#include <bits/stdc++.h>
using namespace std;
int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
int n; string s; cin>>n>>s; int ans=0;
    for(int i=0;i<n;i++)
        if(s[i]=='x' && (i==0 || s[i-1]=='x') && (i+1==n || s[i+1]=='x')) ans++;
    cout<<ans<<'\n';
}
```

